function add(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number' || !Number.isFinite(a) || !Number.isFinite(b)) {
    throw new TypeError('يجب إدخال رقمين صالحين');
  }
  return a + b;
}

console.log(add(3, 5)); // 8

